/**
 * Comment rows, soft deleted so a deleted comment keeps its place in the thread.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, asc, count, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { comments, getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toComment, toUser } from "./_mappers";
import type {
  CreateCommentInput,
  ListCommentsInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type {
  Comment,
  CommentThreadNode,
  CommentWithAuthor,
} from "@/types/comment";
import type { CommentId, IssueId, OrgId, Page, UserId } from "@/types/common";

export async function findCommentById(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment | null> {
  const row = getDb()
    .select()
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .get();
  return row ? toComment(row) : null;
}

export async function listComments(
  input: ListCommentsInput,
): Promise<Page<CommentWithAuthor>> {
  const db = getDb();
  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };

  const filters = compact(
    orgPredicate(comments.orgId, input.orgId),
    eq(comments.issueId, input.issueId),
    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,
  );

  const total = db
    .select({ value: count() })
    .from(comments)
    .where(and(...filters))
    .get();

  const rows = db
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(comments.createdAt), desc(comments.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),
    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),
  );
}

/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. Archived comments are kept so a reply
 * chain never loses its anchor — the UI renders them as "deleted".
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
        isNull(comments.archivedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertComment(
  input: CreateCommentInput,
  authorId: UserId,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toComment(row);
}

/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */
export async function updateComment(
  input: UpdateCommentInput,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        eq(comments.id, input.commentId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${input.commentId} not found`);
  return toComment(row);
}

export async function archiveComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment> {
  const row = getDb()
    .update(comments)
    .set(archivePatch())
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${commentId} not found`);
  return toComment(row);
}
/**
 * Label rows and the issue↔label join table.
 */
import { and, asc, eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueLabels, labels } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toLabel } from "./_mappers";
import type { CreateLabelInput, UpdateLabelInput } from "@/schemas/label";
import type { IssueId, LabelId, OrgId } from "@/types/common";
import type { IssueLabel } from "@/types/issue";

export async function listLabels(
  orgId: OrgId,
): Promise<readonly IssueLabel[]> {
  const rows = getDb()
    .select()
    .from(labels)
    .where(orgPredicate(labels.orgId, orgId))
    .orderBy(asc(labels.name))
    .all();
  return rows.map(toLabel);
}

export async function insertLabel(
  input: CreateLabelInput,
): Promise<IssueLabel> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(labels)
    .values({
      id: newId(),
      orgId: input.orgId,
      name: input.name,
      color: input.color,
      description: input.description,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toLabel(row);
}

export async function updateLabel(
  input: UpdateLabelInput,
): Promise<IssueLabel> {
  const row = getDb()
    .update(labels)
    .set({
      ...(input.name === undefined ? {} : { name: input.name }),
      ...(input.color === undefined ? {} : { color: input.color }),
      ...(input.description === undefined
        ? {}
        : { description: input.description }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(orgPredicate(labels.orgId, input.orgId), eq(labels.id, input.labelId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Label ${input.labelId} not found`);
  return toLabel(row);
}

/** Labels are hard deleted; the join rows go with them. */
export async function deleteLabel(
  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  const db = getDb();
  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, labelId),
      ),
    )
    .run();
  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, labelId)))
    .run();
}

/** Replaces the whole label set of one issue in a single round trip. */
export async function setIssueLabels(
  orgId: OrgId,
  issueId: IssueId,
  labelIds: readonly LabelId[],
): Promise<void> {
  const db = getDb();
  db.delete(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.issueId, issueId),
      ),
    )
    .run();

  if (labelIds.length === 0) return;

  db.insert(issueLabels)
    .values(labelIds.map((labelId) => ({ orgId, issueId, labelId })))
    .run();
}

/** Batched lookup keyed by issue id, so list views avoid an N+1. */
export async function listLabelsForIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<Readonly<Record<string, readonly IssueLabel[]>>> {
  if (issueIds.length === 0) return {};

  const rows = getDb()
    .select({ issueId: issueLabels.issueId, label: labels })
    .from(issueLabels)
    .innerJoin(labels, eq(labels.id, issueLabels.labelId))
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        inArray(issueLabels.issueId, [...issueIds]),
      ),
    )
    .all();

  const grouped: Record<string, IssueLabel[]> = {};
  for (const row of rows) {
    (grouped[row.issueId] ??= []).push(toLabel(row.label));
  }
  return grouped;
}
/**
 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, count, desc, eq, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { getDb, members, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toMember, toUser } from "./_mappers";
import type { ListMembersInput } from "@/schemas/member";
import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted, and no read ever surfaces one:
 * the scope is fixed here rather than threaded through every call site.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
  );
}

/** The seat count every plan check compares against. */
export async function countActiveMembers(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

export async function updateMemberRole(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ role, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

/** Removal is a soft delete so the audit log keeps pointing at a real row. */
export async function archiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({ ...archivePatch(), status: "suspended" })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

export async function touchLastSeen(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(members)
    .set({ lastSeenAt: at })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .run();
}
/**
 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { eq, isNull } from "drizzle-orm";
import { shouldFilterArchived } from "@/lib/soft-delete";
import type { ArchiveScope, OrgId } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

const CURSOR_SEPARATOR = "|";

/**
 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 * sort value alongside the id is what lets `listX` resume from a stable point
 * even when two rows share a timestamp.
 */
export function encodeCursor(id: string, sortValue: string): string {
  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    "base64url",
  );
}

export function decodeCursor(
  cursor: string,
): { id: string; sortValue: string } | null {
  let decoded: string;
  try {
    decoded = Buffer.from(cursor, "base64url").toString("utf8");
  } catch {
    return null;
  }

  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;

  return {
    sortValue: decoded.slice(0, separatorAt),
    id: decoded.slice(separatorAt + 1),
  };
}

/**
 * The tenant predicate. Every repository read and write composes this — a
 * query that does not mention `org_id` is a cross-tenant leak waiting to
 * happen, so this is the only sanctioned way to express it.
 */
export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
  return eq(column, orgId);
}

/**
 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 * for archived rows. The `includeArchived` decision itself lives in
 * `shouldFilterArchived()` so it cannot drift per repository.
 */
export function livePredicate(
  column: SQLiteColumn,
  scope: ArchiveScope,
): SQL | undefined {
  return shouldFilterArchived(scope) ? isNull(column) : undefined;
}
import type { OrgId, TenantScoped } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Multi-tenancy invariant helpers.
 *
 * Every repository query must be filtered by `org_id`, and every row that
 * crosses a service boundary must be re-checked against the actor's org. These
 * helpers are the only sanctioned way to express that — a hand-written
 * `if (row.orgId !== actor.orgId)` is a review failure.
 */

export class TenantScopeError extends Error {
  readonly code = "tenant_scope_violation" as const;

  constructor(
    readonly expectedOrgId: OrgId,
    readonly actualOrgId: OrgId,
  ) {
    super(
      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    );
    this.name = "TenantScopeError";
  }
}

/** Throws unless `orgId` belongs to the actor's organization. */
export function assertOrgScope(actor: Actor, orgId: OrgId): void {
  if (actor.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, orgId);
  }
}

/** Throws unless every supplied row belongs to the actor's organization. */
export function assertRowsInScope<T extends TenantScoped>(
  actor: Actor,
  rows: readonly T[],
): void {
  for (const row of rows) {
    assertOrgScope(actor, row.orgId);
  }
}

/** Non-throwing predicate, for filtering rather than failing. */
export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
  return row.orgId === actor.orgId;
}

/** Narrows a nullable row to one the actor may see; `null` otherwise. */
export function scopedOrNull<T extends TenantScoped>(
  actor: Actor,
  row: T | null | undefined,
): T | null {
  if (!row) return null;
  return row.orgId === actor.orgId ? row : null;
}

/**
 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
 * cannot forget it. Always spread the caller filter first.
 */
export function withOrgScope<T extends object>(
  actor: Actor,
  filter: T,
): T & { orgId: OrgId } {
  return { ...filter, orgId: actor.orgId };
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

