async function assertParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null) {
